struct Dedup<I: Iterator> {
    inner: I,
    last: Option<I::Item>,
}

impl<I: Iterator> Iterator for Dedup<I> where I::Item: PartialEq + Clone {
    type Item = I::Item;
    fn next(&mut self) -> Option<Self::Item> {
        loop {
            let item = self.inner.next()?;
            if self.last.as_ref() != Some(&item) {
                self.last = Some(item.clone());
                return Some(item);
            }
        }
    }
}
